182	
183	// moveRepoStorageAside retires both halves of one store.
184	//
185	// The head store is a per-key DIRECTORY (it holds the export cursor alongside
186	// the setup record and the watch cursor), so it moves with its brain. Leaving
187	// the head behind would leave the conflict standing -- repoStorageContainsState
188	// counts either half, so a retired brain with a live head is still a second
189	// identity.
190	func moveRepoStorageAside(out io.Writer, storage repoStorage, suffix string) error {
191		for _, dir := range []string{storage.BrainDir, filepath.Dir(storage.HeadPath)} {
192			moved, err := moveRepoStoreAside(dir, suffix)
193			if err != nil {
194				return err
195			}
196			if moved != "" {
197				fmt.Fprintf(out, "moved aside: %s -> %s\n", dir, moved)
198			}
199		}
200		return nil
201	}
202	
203	// promoteRepoStorage renames a kept store onto the canonical key.
204	//
205	// Each half is one os.Rename within a single filesystem, so each is atomic:
206	// nothing is ever half-copied. The two renames are not atomic TOGETHER, and
207	// that is the residual risk. A crash between them leaves the brain at the
208	// canonical key and the head still at the old one -- which reads as two
209	// identities again, so the next command reports the same conflict and this same
210	// command repairs it. Nothing is lost either way, which is why this moves
211	// rather than copies and never removes.
212	func promoteRepoStorage(out io.Writer, kept, canonical repoStorage, suffix string) (repoStorage, error) {
213		// Whatever is sitting at the canonical paths is not the history being kept
214		// (the caller chose against it, or it is an empty shell left by a command
215		// that resolved the key without writing). Retire it rather than write over
216		// it.
217		if err := moveRepoStorageAside(out, canonical, suffix); err != nil {
218			return repoStorage{}, err
219		}
220		moves := [][2]string{
221			{kept.BrainDir, canonical.BrainDir},
222			{filepath.Dir(kept.HeadPath), filepath.Dir(canonical.HeadPath)},
223		}
224		for _, move := range moves {
225			from, to := move[0], move[1]
226			if _, err := os.Lstat(from); err != nil {
227				if errors.Is(err, os.ErrNotExist) {
228					continue
229				}
230				return repoStorage{}, fmt.Errorf("inspect %s: %w", from, err)
231			}
232			if err := os.MkdirAll(filepath.Dir(to), 0o700); err != nil {
233				return repoStorage{}, fmt.Errorf("create %s: %w", filepath.Dir(to), err)
234			}
235			if err := os.Rename(from, to); err != nil {
236				return repoStorage{}, fmt.Errorf("move %s to the canonical key: %w", from, err)
237			}
238			fmt.Fprintf(out, "promoted: %s -> %s\n", from, to)
239		}
240		return canonical, nil
241	}
242	
243	// moveRepoStoreAside renames dir to a timestamped sibling and reports the new
244	// name, or "" when there was nothing there. It refuses to overwrite an existing
245	// set-aside store rather than destroy a previous repair's copy.
246	func moveRepoStoreAside(dir, suffix string) (string, error) {
247		if _, err := os.Lstat(dir); err != nil {
248			if errors.Is(err, os.ErrNotExist) {
249				return "", nil
250			}
251			return "", fmt.Errorf("inspect %s: %w", dir, err)
252		}
253		target := dir + suffix
254		if _, err := os.Lstat(target); err == nil {
255			return "", fmt.Errorf("cannot move %s aside: %s already exists", dir, target)
256		} else if !errors.Is(err, os.ErrNotExist) {
257			return "", fmt.Errorf("inspect %s: %w", target, err)
258		}
259		if err := os.Rename(dir, target); err != nil {
260			return "", fmt.Errorf("move %s aside: %w", dir, err)
261		}
262		return target, nil
263	}
