182	func TestFactWebhookWithholdsTextByDefault(t *testing.T) {
183		t.Setenv(webhookIncludeTextEnv, "")
184		fact := sampleFact()
185		event := newFactWebhookEvent(WebhookFactRecorded, webhookRepoName("/home/someone/work/myrepo"), "main", fact, testNow())
186	
187		encoded, err := json.Marshal(event)
188		if err != nil {
189			t.Fatalf("marshal: %v", err)
190		}
191		if strings.Contains(string(encoded), fact.Text) {
192			t.Fatalf("the fact text was in the payload: %s", encoded)
193		}
194		if event.Fact.Text != "" {
195			t.Fatalf("Text should be empty, got %q", event.Fact.Text)
196		}
197		// Redaction must not cost the subscriber the ability to act: the id, kind
198		// and paths are what make the event useful, and they must survive.
199		if event.Fact.ID != fact.ID || event.Fact.Kind != fact.Kind || len(event.Fact.Paths) != 1 {
200			t.Fatalf("redaction removed more than the text: %+v", event.Fact)
201		}
202		// The repository is identified by name, not by a path that discloses the
203		// layout of somebody's home directory.
204		if event.Repo != "myrepo" {
205			t.Fatalf("Repo = %q, want the directory name", event.Repo)
206		}
207		if strings.Contains(string(encoded), "/home/someone") {
208			t.Fatalf("the payload leaked a filesystem path: %s", encoded)
209		}
210	}
