251	// A receiver can only trust an event it can attribute. The signature has to be
252	// over the exact bytes sent, or verification fails for everyone who implements
253	// it correctly.
254	func TestWebhookSignsThePayloadItActuallySends(t *testing.T) {
255		rec := webhookEndpointServer(t)
256		const secret = "shared-secret"
257		t.Setenv(webhookSecretEnv, secret)
258	
259		if err := emitWebhook(context.Background(), newFactWebhookEvent(
260			WebhookFactRecorded, webhookRepoName("/repo"), "main", sampleFact(), testNow())); err != nil {
261			t.Fatalf("emit: %v", err)
262		}
263		got := rec.last(t)
264		header := got.headers.Get("X-Entire-Signature-256")
265		if header == "" {
266			t.Fatal("no signature header was sent")
267		}
268		mac := hmac.New(sha256.New, []byte(secret))
269		mac.Write(got.body)
270		want := "sha256=" + hex.EncodeToString(mac.Sum(nil))
271		if !hmac.Equal([]byte(header), []byte(want)) {
272			t.Fatalf("signature %s does not verify over the delivered body (want %s)", header, want)
273		}
274		if event := got.headers.Get("X-Entire-Event"); event != WebhookFactRecorded {
275			t.Fatalf("X-Entire-Event = %q, want %q", event, WebhookFactRecorded)
276		}
277	}
