324	// Every event name this brain advertises must be sent by real code somewhere
325	// outside the webhook plumbing. A list a consumer can subscribe to and never
326	// receive anything from is worse than a shorter list.
327	func TestEveryAdvertisedEventIsActuallyEmitted(t *testing.T) {
328		constantFor := map[string]string{
329			WebhookFactRecorded:   "WebhookFactRecorded",
330			WebhookFactRetracted:  "WebhookFactRetracted",
331			WebhookBrainRefreshed: "WebhookBrainRefreshed",
332			WebhookTest:           "WebhookTest",
333		}
334		entries, err := os.ReadDir(".")
335		if err != nil {
336			t.Fatalf("read package dir: %v", err)
337		}
338		var sources []string
339		for _, entry := range entries {
340			name := entry.Name()
341			if entry.IsDir() || !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") {
342				continue
343			}
344			// webhooks.go declares the constants; a reference there proves nothing.
345			if name == "webhooks.go" {
346				continue
347			}
348			data, err := os.ReadFile(filepath.Clean(name))
349			if err != nil {
350				t.Fatalf("read %s: %v", name, err)
351			}
352			sources = append(sources, string(data))
353		}
354		for _, event := range webhookEventNames() {
355			identifier, known := constantFor[event]
356			if !known {
357				t.Fatalf("event %q has no constant in this test; add it and the code that emits it", event)
358			}
359			found := false
360			for _, source := range sources {
361				if strings.Contains(source, identifier) {
362					found = true
363					break
364				}
365			}
366			if !found {
367				t.Fatalf("%s (%s) is advertised but nothing outside webhooks.go emits it", event, identifier)
368			}
369		}
