681	// Delivery is on the critical path of every command that triggers it, and
682	// `remember` is called by agents often. The timeout is therefore a latency
683	// budget, and a slow endpoint must cost about that and not more.
684	func TestASlowEndpointCostsAtMostTheTimeout(t *testing.T) {
685		stall := make(chan struct{})
686		server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
687			<-stall // accept the connection, then never respond
688		}))
689		// Cleanups run last-registered-first, so the stall must be released AFTER
690		// this is registered: Close waits for outstanding handlers, and releasing
691		// second would deadlock the test rather than the product.
692		t.Cleanup(server.Close)
693		t.Cleanup(func() { close(stall) })
694		t.Setenv(webhookURLEnv, server.URL)
695		t.Setenv(webhookTimeoutEnv, "300ms")
696	
697		start := time.Now()
698		err := emitWebhook(context.Background(), webhookEvent{Event: WebhookTest})
699		elapsed := time.Since(start)
700	
701		if err == nil {
702			t.Fatal("a stalled endpoint was reported as a successful delivery")
703		}
704		if elapsed > 3*time.Second {
705			t.Fatalf("a stalled endpoint blocked for %s; the timeout is not bounding it", elapsed)
706		}
707		if elapsed < 250*time.Millisecond {
708			t.Fatalf("delivery gave up after %s, well before the configured timeout", elapsed)
709		}
710	}
