733	// onto every `remember` that has a webhook configured.
734	func TestDefaultWebhookTimeoutStaysABudget(t *testing.T) {
735		if defaultWebhookTimeout > 2*time.Second {
736			t.Fatalf("the default timeout is %s; delivery is synchronous, so this is charged to every triggering command",
737				defaultWebhookTimeout)
