741	// For many receivers the URL is the credential — a Slack or Discord incoming
742	// webhook is a secret path. The transport error embeds the whole URL and is
743	// printed to stderr on every transient failure, into CI logs, agent transcripts
744	// and error monitoring. The host is enough to diagnose; the rest is a secret.
745	func TestDeliveryFailureDoesNotLeakTheEndpoint(t *testing.T) {
746		const secretPath = "/services/T00000000/B00000000/XXXXXXXXXXXXsecrettoken"
747		// A port nothing is listening on, so the POST fails at the transport.
748		t.Setenv(webhookURLEnv, "http://127.0.0.1:1"+secretPath+"?token=alsosecret")
749	
750		err := emitWebhook(context.Background(), webhookEvent{Event: WebhookTest})
751		if err == nil {
752			t.Fatal("delivery to a dead port reported success")
753		}
754		message := err.Error()
755		for _, secret := range []string{secretPath, "secrettoken", "alsosecret"} {
756			if strings.Contains(message, secret) {
757				t.Fatalf("the delivery error leaks the endpoint: %q", message)
758			}
759		}
760		// And the same through the path the write commands actually use.
761		errOut := &bytes.Buffer{}
762		notifyWebhook(context.Background(), errOut, webhookEvent{Event: WebhookTest})
763		for _, secret := range []string{secretPath, "secrettoken", "alsosecret"} {
764			if strings.Contains(errOut.String(), secret) {
765				t.Fatalf("the stderr warning leaks the endpoint: %q", errOut.String())
766			}
767		}
768		// It still has to be diagnosable: the host and the reason must survive.
769		if !strings.Contains(message, "127.0.0.1") {
770			t.Fatalf("redaction removed the host, leaving nothing to diagnose: %q", message)
771		}
772		if !strings.Contains(strings.ToLower(message), "refused") && !strings.Contains(strings.ToLower(message), "connect") {
773			t.Fatalf("redaction removed the reason: %q", message)
774		}
775	}
