777	// Every event for one repository must report the same `repo`, or a subscriber
778	// correlating by it sees two repositories where there is one. The call sites
779	// had drifted between the git toplevel and the configured root, which differ
780	// whenever a repository is reached through a symlink or from a subdirectory.
781	func TestEveryWebhookCallSiteUsesOneRepoIdentity(t *testing.T) {
782		entries, err := os.ReadDir(".")
783		if err != nil {
784			t.Fatal(err)
785		}
786		for _, entry := range entries {
787			name := entry.Name()
788			if entry.IsDir() || !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") || name == "webhooks.go" {
789				continue
790			}
791			data, err := os.ReadFile(filepath.Clean(name))
792			if err != nil {
793				t.Fatal(err)
794			}
795			for _, line := range strings.Split(string(data), "\n") {
796				if !strings.Contains(line, "webhookRepoName(") {
797					continue
798				}
799				t.Fatalf("%s builds a webhook repo name directly:\n  %s\nuse webhookRepoIdentity so every event names the repository the same way",
800					name, strings.TrimSpace(line))
801			}
802		}
803	}
